const rawContent = $input.first().json.choices[0].message.content;
let clasificacion;
try {
  clasificacion = JSON.parse(rawContent);
} catch(e) {
  clasificacion = { intencion: 'CONSULTAR', es_urgente: false, area_estimada: 'desconocida', resumen: 'No clasificado' };
}

// ── OVERRIDE DE SEGURIDAD: saludos y msgs cortos → siempre CONSULTAR ──────
const msg = ($('GESTOR DE ESTADO').first().json.chatInput || '').trim().toLowerCase();
const SALUDOS = ['hola', 'buenas', 'buenos', 'buen dia', 'good morning', 'hi', 'hello',
                 'hey', 'saludos', 'buenas!', 'hola!', 'ola', 'ke tal', 'qué tal'];
const esCortoOSaludo = msg.length <= 25 ||
  SALUDOS.some(g => msg === g || msg.startsWith(g + ' ') || msg.startsWith(g + '!'));

if (esCortoOSaludo && clasificacion.intencion === 'NO_CALIFICA') {
  clasificacion.intencion = 'CONSULTAR';
  clasificacion.resumen = 'Saludo inicial';
}

const ges = $('GESTOR DE ESTADO').first().json;
return {
  necesidad: clasificacion.intencion || 'CONSULTAR',
  urgencia: clasificacion.es_urgente || false,
  area: clasificacion.area_estimada || 'desconocida',
  resumenNecesidad: clasificacion.resumen || '',
  esReclasificado: true,
  chatInput: ges.chatInput,
  telefono: ges.telefono,
  nombreCliente: ges.nombreWhatsApp,
  fechaHoraHoy: ges.fechaHoraHoy,
  esNuevoPaciente: ges.esNuevoPaciente,
  nombreEnDB: ges.nombreEnDB,
  faseConsulta: ges.faseConsulta || 'Sin consulta previa',
  calendarId: ges.calendarId,
  datosParciales: {}
};

const ges = $('GESTOR DE ESTADO').first().json;

const base = {
  chatInput: ges.chatInput,
  telefono: ges.telefono,
  nombreCliente: ges.nombreWhatsApp || ges.nombreEnDB || 'Prospecto',
  fechaHoraHoy: ges.fechaHoraHoy,
  esNuevoPaciente: ges.esNuevoPaciente,
  nombreEnDB: ges.nombreEnDB,
  faseConsulta: ges.faseConsulta || 'Sin consulta previa',
  calendarId: ges.calendarId || '',
  datosParciales: {}
};

let necesidadFinal, urgenciaFinal, resumenFinal;

if (ges.estadoActivo === true) {
  // ── SESIÓN ACTIVA: reclasifica el mensaje pero respeta el agente en curso ──
  let nueva;
  try {
    nueva = $('PARSER CLASIFICADOR1').first().json;
  } catch(e) {
    nueva = { necesidad: ges.necesidad || 'CONSULTAR', urgencia: false, resumenNecesidad: '' };
  }

  // Solo cambia de agente si el usuario pide explícitamente otra acción
  const CAMBIOS_EXPLICITOS = ['AGENDAR', 'REAGENDAR', 'CANCELAR'];
  const cambioExplicito = CAMBIOS_EXPLICITOS.includes(nueva.necesidad) &&
                          nueva.necesidad !== ges.necesidad;

  necesidadFinal  = cambioExplicito ? nueva.necesidad  : (ges.necesidad || 'CONSULTAR');
  urgenciaFinal   = nueva.urgencia  || false;
  resumenFinal    = nueva.resumenNecesidad || '';

} else {
  // ── SESIÓN NUEVA: usar clasificación fresca del mensaje ──
  let nueva;
  try {
    nueva = $('PARSER CLASIFICADOR').first().json;
  } catch(e) {
    nueva = { necesidad: 'CONSULTAR', urgencia: false, resumenNecesidad: '' };
  }
  necesidadFinal = nueva.necesidad  || 'CONSULTAR';
  urgenciaFinal  = nueva.urgencia   || false;
  resumenFinal   = nueva.resumenNecesidad || '';
}

return {
  ...base,
  necesidad:        necesidadFinal,
  urgencia:         urgenciaFinal,
  resumenNecesidad: resumenFinal,
  estadoPrevio:     ges.estadoActivo ? ges.necesidad : null
};

