// Extrae teléfono del admin desde el webhook (antes de PREPARADOR DE DATOS)
const data = $('Webhook').first().json;
const remoteJid = data.body?.data?.key?.remoteJid || '';
const telefono = remoteJid.replace('@s.whatsapp.net', '');
return { telefono };

const { 
  tipo_accidente, 
  lesiones, 
  fecha_accidente, 
  situacion, 
  tratamiento, 
  nombre, 
  email 
} = $input;

const ges = $('GESTOR DE ESTADO').first().json;

// Empaquetar todo el formulario en el campo 'consulta' limpiamente para Supabase
const fichaFormateada = `🔴 Accidente: ${tipo_accidente}
🤕 Lesiones: ${lesiones}
📅 Fecha: ${fecha_accidente}
📋 Situación: ${situacion}
🏥 Tratamiento: ${tratamiento}`;

const body = {
  telefono: ges.telefono,
  nombre: nombre || 'Prospecto',
  consulta: fichaFormateada,
  area_legal: tipo_accidente.toLowerCase().includes('transito') ? 'transito' : 'laboral',
  urgencia: lesiones.toLowerCase() === 'sí' || lesiones.toLowerCase() === 'si',
  email: email || '',
  calificacion: 'INTERESADO',
  estado_actual: null,
  ultima_actividad: new Date().toISOString()
};

const options = {
  method: 'POST',
  uri: 'https://nqsqyugkiqectlysfpkg.supabase.co/rest/v1/leads?on_conflict=telefono',
  json: true,
  headers: {
    'Content-Type': 'application/json',
    'Prefer': 'resolution=merge-duplicates,return=minimal'
  },
  body: body
};

try {
  await this.helpers.requestWithAuthentication('supabaseApi', options);
  return 'ÉXITO: Ficha guardada. Despídete usando las instrucciones del prompt con la etiqueta secreta.';
} catch (error) {
  return 'ERROR: ' + error.message;
}

let msg = $json.output || "";
let newLead = false;
if (msg.includes("|||NEW_LEAD|||")) {
  newLead = true;
  msg = msg.replace("|||NEW_LEAD|||", "").trim();
}
// Retornamos el payload original pero modificado
return {
  ...$json,
  output: msg,
  isNewLead: newLead
};
